:root {
  --bg: #1b1f2a;
  --bg-accent: #232a3a;
  --card: #f7f8fb;
  --ink: #1b1f2a;
  --muted: #5a6274;
  --accent: #5b6cff;
  --accent-press: #4453d6;
  --focus: #ffb703;
  --radius: 16px;
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--ink);
  background: radial-gradient(circle at 20% 10%, #2c3550 0%, var(--bg) 55%, #12151d 100%);
}

.card {
  width: 100%;
  max-width: 720px;
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 28px;
}

.card-header {
  margin-bottom: 20px;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.75rem;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
}

.swatches {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 24px;
}

.swatch {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 180px;
  border-radius: 12px;
  padding: 12px;
  border: 2px solid rgba(0, 0, 0, 0.08);
  transition: transform 120ms ease, box-shadow 120ms ease;
}

.swatch:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.18);
}

.hex {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  user-select: all;
}

.lock-btn {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font: inherit;
  font-size: 0.85rem;
  font-weight: 600;
  padding: 6px 10px;
  border-radius: 999px;
  border: 2px solid currentColor;
  background: rgba(255, 255, 255, 0.22);
  color: inherit;
  cursor: pointer;
  transition: background 120ms ease, transform 80ms ease;
}

.lock-btn:hover {
  background: rgba(255, 255, 255, 0.4);
}

.lock-btn:active {
  transform: scale(0.96);
}

.lock-btn[aria-pressed="true"] {
  background: rgba(255, 255, 255, 0.85);
  color: #111;
}

.lock-btn:focus-visible,
.btn-generate:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.actions {
  display: flex;
  justify-content: center;
}

.btn-generate {
  font: inherit;
  font-size: 1.05rem;
  font-weight: 700;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 999px;
  padding: 14px 32px;
  cursor: pointer;
  transition: background 120ms ease, transform 80ms ease, box-shadow 120ms ease;
  box-shadow: 0 8px 20px rgba(91, 108, 255, 0.35);
}

.btn-generate:hover {
  background: #4d5df0;
}

.btn-generate:active {
  background: var(--accent-press);
  transform: translateY(1px) scale(0.99);
  box-shadow: 0 4px 12px rgba(91, 108, 255, 0.3);
}

@media (max-width: 560px) {
  .card {
    padding: 20px;
  }

  .swatches {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .swatch {
    min-height: 130px;
  }

  .swatch:last-child {
    grid-column: 1 / -1;
  }
}

@media (max-width: 360px) {
  .swatches {
    grid-template-columns: 1fr;
  }

  .swatch:last-child {
    grid-column: auto;
  }
}

(function () {
  'use strict';

  var SWATCH_COUNT = 5;
  var swatchesEl = document.getElementById('swatches');
  var generateBtn = document.getElementById('generate');

  // state: array of { hex, locked }
  var state = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var c = (1 - Math.abs(2 * l - 1)) * s;
    var x = c * (1 - Math.abs(((h / 60) % 2) - 1));
    var m = l - c / 2;
    var r = 0, g = 0, b = 0;

    if (h >= 0 && h < 60) { r = c; g = x; b = 0; }
    else if (h < 120) { r = x; g = c; b = 0; }
    else if (h < 180) { r = 0; g = c; b = x; }
    else if (h < 240) { r = 0; g = x; b = c; }
    else if (h < 300) { r = x; g = 0; b = c; }
    else { r = c; g = 0; b = x; }

    function toHex(v) {
      var n = Math.round((v + m) * 255);
      var str = n.toString(16).toUpperCase();
      return str.length === 1 ? '0' + str : str;
    }

    return '#' + toHex(r) + toHex(g) + toHex(b);
  }

  function hexToRgb(hex) {
    var h = hex.replace('#', '');
    return {
      r: parseInt(h.slice(0, 2), 16),
      g: parseInt(h.slice(2, 4), 16),
      b: parseInt(h.slice(4, 6), 16)
    };
  }

  function luminance(hex) {
    var rgb = hexToRgb(hex);
    var channels = [rgb.r, rgb.g, rgb.b].map(function (c) {
      var v = c / 255;
      return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    });
    return 0.2126 * channels[0] + 0.7152 * channels[1] + 0.0722 * channels[2];
  }

  function readableInk(hex) {
    return luminance(hex) > 0.45 ? '#111318' : '#ffffff';
  }

  // Generate a harmonious set of HSL colors. Strategy rotates per generate.
  var strategies = ['analogous', 'complementary', 'triadic', 'split'];
  var strategyIndex = 0;

  function buildHarmoniousColors() {
    var baseHue = Math.floor(Math.random() * 360);
    var strategy = strategies[strategyIndex % strategies.length];
    strategyIndex += 1;

    var hues = [];
    var sat = 62 + Math.random() * 18;
    var lightness = 48 + Math.random() * 12;

    for (var i = 0; i < SWATCH_COUNT; i++) {
      var h;
      if (strategy === 'analogous') {
        h = baseHue + i * 24;
      } else if (strategy === 'complementary') {
        h = i % 2 === 0 ? baseHue + i * 6 : baseHue + 180 + i * 6;
      } else if (strategy === 'triadic') {
        h = baseHue + [0, 120, 240, 120, 240][i];
      } else {
        h = baseHue + [0, 150, 210, 30, 180][i];
      }
      h = ((h % 360) + 360) % 360;
      hues.push(h);
    }

    return hues.map(function (h, idx) {
      var l = lightness + (idx - 2) * 6;
      l = Math.max(30, Math.min(72, l));
      return { hex: hslToHex(h, sat, l), locked: false };
    });
  }

  function generate() {
    var fresh = buildHarmoniousColors();
    var next = [];
    for (var i = 0; i < SWATCH_COUNT; i++) {
      if (state[i] && state[i].locked) {
        next.push({ hex: state[i].hex, locked: true });
      } else {
        next.push({ hex: fresh[i].hex, locked: false });
      }
    }
    state = next;
    render();
  }

  function toggleLock(index) {
    if (!state[index]) return;
    state[index].locked = !state[index].locked;
    render();
  }

  function render() {
    swatchesEl.innerHTML = '';

    state.forEach(function (swatch, index) {
      var ink = readableInk(swatch.hex);
      var card = document.createElement('div');
      card.className = 'swatch';
      card.style.backgroundColor = swatch.hex;
      card.style.color = ink;

      var hexEl = document.createElement('span');
      hexEl.className = 'hex';
      hexEl.textContent = swatch.hex;

      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'lock-btn';
      btn.setAttribute('aria-pressed', swatch.locked ? 'true' : 'false');
      btn.setAttribute('aria-label', (swatch.locked ? 'Unlock' : 'Lock') + ' color ' + swatch.hex);
      btn.textContent = swatch.locked ? '\uD83D\uDD12 Locked' : '\uD83D\uDD13 Lock';
      btn.addEventListener('click', function () {
        toggleLock(index);
      });

      card.appendChild(hexEl);
      card.appendChild(btn);
      swatchesEl.appendChild(card);
    });
  }

  generateBtn.addEventListener('click', generate);

  // Initial palette
  state = buildHarmoniousColors();
  render();
})();
